function help(id){const g=GAMES[id];const instructions={quiz:'Everyone answers on their phone. Correct answers earn 100 points. The host reveals the story and advances the questions.',bluff:'Write a convincing invented ending to a story. Then identify the real answer. Find the truth for 200 points; fool someone for 100.',kruger:'Four chapters on a map based on Krugerplein. Move with arrows, pick up items with Action, then deliver them to the green flag. A sofa needs another player nearby. All four chapters share one minigame score.',restore:'Restore the shared landscape before time runs out. Clear litter, plant trees, water seedlings and place coral. Heatwaves threaten restored habitats: rescue them before they disappear. Chain actions for combos, manage energy, and find golden seeds for a rush boost. Your trees keep earning points as they grow.',sketch:'Everyone draws a secret prompt on their phone. The host reveals drawings one at a time. Guess the prompt; both artist and correct guessers earn points. The host can accept near matches.'};const el=document.createElement('div');el.className='help-dialog';el.innerHTML=`<div><p class="eyebrow">${g.genre}</p><h2>${esc(g.title)}</h2><p>${instructions[id]}</p><p>Host a party on the shared screen, then join that room from your phone.</p><button class="btn primary" data-close>CLOSE</button></div>`;document.body.append(el);el.querySelector('[data-close]').onclick=()=>el.remove();el.onclick=e=>{if(e.target===el)el.remove();};}
function download(name,text){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function setupDrawing(){drawing=[];stroke=null;drawingSent=false;const canvas=$('#draw');const point=e=>{const b=canvas.getBoundingClientRect();return[Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))];};canvas.onpointerdown=e=>{if(drawing.length>=180)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);stroke=[point(e)];drawing.push(stroke);};canvas.onpointermove=e=>{if(!stroke||stroke.length>=400)return;stroke.push(point(e));paintDrawing(canvas,drawing);};canvas.onpointerup=canvas.onpointercancel=()=>{stroke=null;paintDrawing(canvas,drawing);};$('[data-clear-drawing]').onclick=()=>{drawing=[];paintDrawing(canvas,drawing);};$('[data-send-drawing]').onclick=async()=>{await play({type:'drawing',strokes:drawing});drawingSent=true;if($('#drawing-status'))$('#drawing-status').textContent='DRAWING SAVED. YOU CAN UPDATE IT UNTIL THE TIMER ENDS.';};paintDrawing(canvas,drawing);}
function paintDrawing(canvas,strokes){const ctx=canvas.getContext('2d');ctx.fillStyle='#fffdf4';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.strokeStyle='#103c34';ctx.lineWidth=6;ctx.lineCap='round';ctx.lineJoin='round';for(const points of strokes){if(!points.length)continue;ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x*canvas.width,y*canvas.height):ctx.moveTo(x*canvas.width,y*canvas.height));if(points.length===1)ctx.lineTo(points[0][0]*canvas.width+.1,points[0][1]*canvas.height+.1);ctx.stroke();}}
async function sendMove(){if(!mapPosition||(!session&&!previewMode)||room?.game?.type!=='kruger')return;try{accept(await request('player',{action:{type:'move',x:mapPosition.x,y:mapPosition.y,seq:++moveSeq}}));}catch{} }
function animateWorld(){let last=performance.now();const loop=t=>{if(!$('#world')||room?.game?.type!=='kruger')return;const dt=Math.min(.06,(t-last)/1000);last=t;if(mapPosition&&(direction.x||direction.y)){const len=Math.hypot(direction.x,direction.y);const next={x:mapPosition.x+direction.x/len*100*dt,y:mapPosition.y+direction.y/len*100*dt};if(walkable(next))mapPosition=next;if(t-moveLast>350){moveLast=t;sendMove();}}drawMap($('#world'),room,false,mapPosition);animation=requestAnimationFrame(loop);};animation=requestAnimationFrame(loop);}
function drawMap(canvas,state,preview=false,position=null){const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;ctx.save();ctx.clearRect(0,0,canvas.width,canvas.height);if(preview){ctx.translate(-90,-120);ctx.scale(.85,.65);}else {const w=state?.me?400:620,h=w*926/1000;const player=position||state?.players.find(p=>p.id===state?.me);const left=player?Math.max(120,Math.min(520,player.x-w/2)):190;const top=player?Math.max(70,Math.min(450,player.y-h/2)):115;ctx.scale(canvas.width/w,canvas.height/h);ctx.translate(-left,-top);}ctx.fillStyle='#b9bba0';ctx.fillRect(0,0,1100,1000);
const poly=(points,fill,stroke)=>{ctx.beginPath();points.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}};
for(const line of MAP.roads){ctx.beginPath();line.forEach(([x,y],i)=>i?ctx.lineTo(x,y):ctx.moveTo(x,y));ctx.lineWidth=57;ctx.strokeStyle='#a9a99b';ctx.stroke();ctx.lineWidth=34;ctx.strokeStyle='#828e86';ctx.stroke();ctx.lineWidth=1;ctx.strokeStyle='#b9bba5';ctx.setLineDash([7,10]);ctx.stroke();ctx.setLineDash([]);}
poly(MAP.square,'#c9c8a7','#afb392');ctx.strokeStyle='#aaa98b';ctx.lineWidth=1;for(let y=330;y<590;y+=17){ctx.beginPath();ctx.moveTo(372,y);ctx.lineTo(570,y);ctx.stroke();}
MAP.buildings.forEach((p,i)=>{const h=14+(i%3)*5;poly(p.map(([x,y])=>[x+6,y+6]),'#70776b');poly(p,['#997f69','#aaa18b','#b09278'][i%3]);poly(p.map(([x,y])=>[x-5,y-h]),['#d2ba94','#b8b29d','#d9c3a0'][i%3],'#7d8271');const a=p[0],b=p[1];for(let t=.15;t<.9;t+=.16){const x=a[0]+(b[0]-a[0])*t,y=a[1]+(b[1]-a[1])*t;ctx.fillStyle='#536d66';ctx.fillRect(x-3,y-h+4,7,8);}});
for(const [x,y]of MAP.trees){ctx.fillStyle='#8b9a76';ctx.fillRect(x+8,y+10,17,8);ctx.fillStyle='#736d4b';ctx.fillRect(x-2,y-5,5,18);ctx.fillStyle='#557d59';ctx.fillRect(x-12,y-24,27,22);ctx.fillStyle='#779861';ctx.fillRect(x-8,y-32,20,14);ctx.fillStyle='#8aa66c';ctx.fillRect(x-4,y-30,10,5);}
ctx.fillStyle='#9e9676';ctx.fillRect(477,388,18,67);ctx.fillRect(506,388,18,67);ctx.strokeStyle='#77785c';ctx.strokeRect(477,388,18,67);ctx.strokeRect(506,388,18,67);
ctx.fillStyle='#8aa5a0';ctx.fillRect(482,487,22,13);ctx.fillStyle='#696c57';ctx.fillRect(490,468,7,23);ctx.fillStyle='#929071';ctx.fillRect(486,464,16,7);
ctx.fillStyle='#ece2bf';ctx.fillRect(365,535,27,17);ctx.fillStyle='#a47b58';ctx.fillRect(368,538,21,7);ctx.fillStyle='#515c50';ctx.fillRect(368,552,5,5);ctx.fillRect(383,552,5,5);
const label=(text,x,y,bg='#103c34',fg='#f7f3df')=>{ctx.font='bold 9px monospace';const w=ctx.measureText(text).width+12;ctx.fillStyle=bg;ctx.fillRect(x-w/2,y-13,w,16);ctx.fillStyle=fg;ctx.textAlign='center';ctx.fillText(text,x,y-2);};
label('BASNOE',467,170);label('CAFÉ OOST',492,634);label('SUMTHING 36A',425,609);label('KARIMA',367,531);label('BOULES',505,377,'#a8b88e','#103c34');label('KRUGERPLEIN',490,307,'#c7c7a7','#315444');
if(!preview){label('N ↑',940,50,'#103c34');ctx.fillStyle='#e4dfc1';ctx.fillRect(354,504,39,18);ctx.fillStyle='#f1eee0';ctx.fillRect(379,507,15,15);ctx.fillStyle='#344c42';ctx.fillRect(355,522,7,5);ctx.fillRect(383,522,7,5);label('VAN',374,503);
ctx.strokeStyle='#d8f57a';ctx.lineWidth=3;ctx.strokeRect(MAP.exit.x-10,MAP.exit.y-7,20,14);}
const g=state?.game;const my=state?.players.find(p=>p.id===state.me);const avatar=(p,npc=false)=>{const x=Math.round(p.x),y=Math.round(p.y);ctx.fillStyle='#203c3433';ctx.fillRect(x-7,y+4,16,5);ctx.fillStyle=p.color;ctx.fillRect(x-6,y-11,13,13);ctx.fillRect(x-8,y-8,3,11);ctx.fillRect(x+7,y-8,3,11);ctx.fillStyle='#d6a078';ctx.fillRect(x-5,y-23,11,12);ctx.fillStyle='#534736';ctx.fillRect(x-5,y-24,11,4);ctx.fillStyle='#13382f';ctx.fillRect(x-3,y-17,2,2);ctx.fillRect(x+2,y-17,2,2);ctx.fillRect(x-5,y+2,4,7);ctx.fillRect(x+2,y+2,4,7);if(!preview)label(p.name,x,y-28,npc?'#67775b':p.id===state?.me?'#d9f86e':'#103c34',p.id===state?.me?'#103c34':'#fff9e8');};
if(g){for(const t of g.tasks||[]){if(t.done||t.owner)continue;ctx.fillStyle=t.heavy?'#d7a7ed':'#f3ad6f';ctx.fillRect(t.x-6,t.y-7,12,12);ctx.strokeStyle='#765741';ctx.lineWidth=1;ctx.strokeRect(t.x-6,t.y-7,12,12);if(my&&distance(position||my,t)<50)label(t.name,t.x,t.y-12,'#f4c48e','#103c34');}
for(const n of g.npcs||[])avatar(n,true);for(const v of g.visitors||[])avatar({...v,name:'Walk-in applicant',color:'#f0b2b5'},true);
const carry=my&&g.tasks?.find(t=>t.id===my.carry);if(carry){ctx.fillStyle='#103c34';ctx.fillRect(carry.to.x,carry.to.y-27,3,27);ctx.fillStyle='#d9f86e';ctx.fillRect(carry.to.x+3,carry.to.y-27,22,13);label('DELIVER HERE',carry.to.x+8,carry.to.y-34,'#d9f86e','#103c34');}
for(const p of [...state.players].sort((a,b)=>a.y-b.y)){const draw=p.id===state.me&&position?{...p,...position}:p;avatar(draw);if(p.carry){ctx.fillStyle='#eeb47a';ctx.fillRect(draw.x-5,draw.y-36,11,9);}}}
ctx.restore();}
window.addEventListener('keydown',e=>{if(room?.game?.type!=='kruger'||room.host||/INPUT|TEXTAREA/.test(e.target.tagName))return;const dirs={ArrowUp:{x:0,y:-1},w:{x:0,y:-1},ArrowDown:{x:0,y:1},s:{x:0,y:1},ArrowLeft:{x:-1,y:0},a:{x:-1,y:0},ArrowRight:{x:1,y:0},d:{x:1,y:0}};if(dirs[e.key]){e.preventDefault();direction=dirs[e.key];}if(e.code==='Space'){e.preventDefault();play({type:'interact'});}});
window.addEventListener('keyup',()=>direction={x:0,y:0});window.addEventListener('blur',()=>direction={x:0,y:0});document.addEventListener('visibilitychange',()=>{direction={x:0,y:0};if(!document.hidden)poll();});
setInterval(poll,750);setInterval(live,250);render();if(GAMES[params.get('preview')])startPreview(params.get('preview'));else if(session)poll();

function previewHeader(){const g=room.game;const labels={quiz:room.game.phase==='answer'?'Reveal answer':'Next question',bluff:room.game.phase==='write'?'Start voting':room.game.phase==='vote'?'Reveal truth':'Next character',kruger:room.game.phase==='chapter'?'End chapter':'Next chapter',restore:'Finish preview',sketch:room.game.phase==='draw'?'Show drawings':room.game.phase==='guess'?'Reveal drawing':'Next drawing'};return `${header()}<section class="preview-toolbar"><div><span class="preview-status">LOCAL PLAYABLE PREVIEW</span><p>Just you + two simulated teammates. No room needed.</p></div><select id="preview-game" aria-label="Choose a game preview">${Object.entries(GAMES).map(([id,item])=>`<option value="${id}" ${g?.type===id?'selected':''}>${esc(item.title)}</option>`).join('')}</select><div class="actions"><button class="btn small" data-preview-screen>${room.host?'PLAY ON PHONE':'SEE TV SCREEN'}</button>${g.phase!=='results'?`<button class="btn small" data-advance>${labels[g.type]||'Next phase'} →</button>`:''}<button class="btn small" data-preview="${g.type}">RESTART</button><button class="btn small" data-feedback>GIVE FEEDBACK</button><button class="btn small" data-preview-menu>ALL FIVE GAMES</button></div></section>`;}
async function startPreview(type){if(!GAMES[type]||busy)return;busy=true;try{previewEngine??=await import('./server/engine.mjs');previewMode=true;previewScreen='player';session=null;previewBotAt=0;previewStarted=Date.now();previewState=previewEngine.createRoom('DEMO','preview-host',Date.now(),true);if(type==='sketch')previewState.pack.sketch=['A sofa','An office','A tree'];['You','Moss Bot','Reef Bot'].forEach((name,i)=>previewEngine.joinRoom(previewState,name,'preview-'+i,Date.now()));previewEngine.hostAction(previewState,{type:'start',game:type,duration:180},Date.now());history.replaceState({},'','?preview='+type);key='';room=null;accept(previewView());}catch(e){toast(e.message);}finally{busy=false;}}
function previewView(){previewState.revision++;return previewEngine.view(previewState,previewScreen==='host'?'preview-host':'preview-0',Date.now());}
function stopPreview(){previewMode=false;previewState=null;previewScreen='player';room=null;session=null;clockOffset=0;window.joinMode=false;history.replaceState({},'','?preview=all');key='';render();$('#games')?.scrollIntoView({behavior:'smooth'});}
function previewRequest(op,data={}){const t=Date.now();previewEngine.tick(previewState,t);for(const p of previewState.players)p.seen=t;if(op==='host')previewEngine.hostAction(previewState,data.action,t);if(op==='player')previewEngine.playerAction(previewState,previewState.players[0],data.action,t);
 const g=previewState.game;if(g&&g.phase!=='results'&&t-previewBotAt>1100){previewBotAt=t;for(let i=1;i<3;i++){const p=previewState.players[i];try{
 if(g.type==='quiz'&&g.phase==='answer'&&!(p.id in g.answers))previewEngine.playerAction(previewState,p,{type:'answer',answer:(previewState.pack.quiz[g.index].correct+i-1)%4},t);
 if(g.type==='bluff'&&g.phase==='write'&&!(p.id in g.bluffs))previewEngine.playerAction(previewState,p,{type:'bluff',text:['A suitcase containing only office snacks','A handwritten business plan for a pigeon café'][i-1]},t);
 if(g.type==='bluff'&&g.phase==='vote'&&!(p.id in g.votes)){const options=g.options.filter(o=>o.owner!==p.id);previewEngine.playerAction(previewState,p,{type:'vote',option:options[(i-1)%options.length].id},t);}
 if(g.type==='sketch'&&g.phase==='draw'&&!(p.id in g.drawings))previewEngine.playerAction(previewState,p,{type:'drawing',strokes:i===1?[[[.25,.8],[.25,.3],[.75,.3],[.75,.8],[.25,.8]],[[.2,.3],[.5,.08],[.8,.3]],[[.45,.8],[.45,.55],[.58,.55],[.58,.8]]]:[[[.5,.85],[.5,.38]],[[.25,.5],[.5,.14],[.75,.5],[.25,.5]],[[.2,.66],[.5,.35],[.8,.66],[.2,.66]]]},t);
 if(g.type==='sketch'&&g.phase==='guess'&&t-g.started>8000&&g.artist!==i&&!g.correctGuessers.includes(p.id))previewEngine.playerAction(previewState,p,{type:'guess',text:g.prompts[previewState.players[g.artist].id]},t);
 if(g.type==='kruger'&&g.phase==='chapter'){const you=previewState.players[0];const pos={x:you.x+(i===1?-20:20),y:you.y+15};if(walkable(pos)){p.x=pos.x;p.y=pos.y;}}
 if(g.type==='restore'&&g.phase==='restore'&&g.cells){const candidates=g.cells.filter(c=>!['rock','tree','coral'].includes(c.type)&&!(c.type==='seedling'&&c.watered));const cell=candidates[(Math.floor((t-previewStarted)/1100)*7+i*23)%Math.max(1,candidates.length)];if(cell){const tool={litter:'clean',soil:'plant',sand:'coral',seedling:'water',fire:'protect',gold:'clean'}[cell.type];if(tool)previewEngine.playerAction(previewState,p,{type:'restore',hits:[{cell:cell.id,tool}]},t);}}
 }catch{}}}return previewView();}
function feedbackDialog(){const type=room?.game?.type||'arcade';let notes={};try{notes=JSON.parse(localStorage.getItem('sumthing-feedback')||'{}');}catch{}const el=document.createElement('div');el.className='help-dialog';el.innerHTML=`<div><p class="eyebrow">YOUR FEEDBACK · ${esc(GAMES[type]?.title||'The arcade')}</p><h2>WHAT SHOULD CHANGE?</h2><p>Notes stay on this device. Save them as you test, then copy everything and paste it into our chat.</p><label for="feedback-note">WHAT WORKS, WHAT DOESN’T, AND YOUR IDEAS</label><textarea id="feedback-note" rows="6" placeholder="For example: the map needs a closer camera…">${esc(notes[type]||'')}</textarea><div class="actions" style="margin-top:15px"><button class="btn lime" data-save-feedback>SAVE NOTE</button><button class="btn" data-copy-notes>COPY ALL FEEDBACK</button><button class="btn" data-close-feedback>CLOSE</button></div></div>`;document.body.append(el);el.querySelector('[data-save-feedback]').onclick=()=>{notes[type]=el.querySelector('textarea').value;localStorage.setItem('sumthing-feedback',JSON.stringify(notes));toast('Feedback saved on this device.');el.remove();};el.querySelector('[data-copy-notes]').onclick=()=>{notes[type]=el.querySelector('textarea').value;localStorage.setItem('sumthing-feedback',JSON.stringify(notes));copyFeedback();};el.querySelector('[data-close-feedback]').onclick=()=>el.remove();}
async function copyFeedback(){let notes={};try{notes=JSON.parse(localStorage.getItem('sumthing-feedback')||'{}');}catch{}const text=Object.entries(notes).filter(([,v])=>v.trim()).map(([k,v])=>(GAMES[k]?.title||k)+'\n'+v).join('\n\n');if(!text){toast('Save a feedback note first.');return;}try{await navigator.clipboard.writeText(text);toast('All feedback copied. Paste it into our chat.');}catch{download('sumthing-feedback.txt',text);}}
function restorationToolText(){return {clean:'CLEAR · Sweep litter out of the way. Golden seeds work with any tool.',plant:'PLANT · Brown soil becomes a seedling. Switch to Water to help it grow.',water:'WATER · Water any dry seedling. The planter earns growth points; you earn care points.',coral:'CORAL · Blue sand becomes living reef. Coral grows after a few seconds.',protect:'RESCUE · Save glowing red habitats before the heatwave destroys them.'}[restoreTool];}
function bindRestoration(){const canvas=$('#restore-board');if(!canvas)return;restorePointer=false;const seen=new Set();const hit=e=>{const b=canvas.getBoundingClientRect(),x=(e.clientX-b.left)/b.width*900,y=(e.clientY-b.top)/b.height*600;const col=Math.floor((x-7)/73),row=Math.floor((y-70)/58);if(col<0||col>=12||row<0||row>=8)return;const id=row*12+col;restoreHover=id;if(room.host||seen.has(id))return;seen.add(id);const c=room.game.cells?.[id];if(!c)return;const valid=c.type==='gold'||({clean:'litter',plant:'soil',water:'seedling',coral:'sand',protect:'fire'}[restoreTool]===c.type&&!(restoreTool==='water'&&c.watered));if(!valid)return;if(restoreQueue.length<8)restoreQueue.push({cell:id,tool:restoreTool});};canvas.onpointerdown=e=>{if(room.host)return;e.preventDefault();canvas.setPointerCapture(e.pointerId);restorePointer=true;seen.clear();hit(e);flushRestoration();};canvas.onpointermove=e=>{if(restorePointer){e.preventDefault();hit(e);}};canvas.onpointerup=canvas.onpointercancel=()=>{restorePointer=false;seen.clear();flushRestoration();};$$('[data-tool]').forEach(b=>b.onclick=()=>{restoreTool=b.dataset.tool;$$('[data-tool]').forEach(el=>el.classList.toggle('active',el.dataset.tool===restoreTool));if($('#restore-instruction'))$('#restore-instruction').textContent=restorationToolText();});if($('#restore-instruction'))$('#restore-instruction').textContent=restorationToolText();}
async function flushRestoration(){if(restoreSending||!restoreQueue.length||room?.game?.phase!=='restore')return;const hits=restoreQueue.splice(0,8);restoreSending=true;try{accept(await request('player',{action:{type:'restore',hits}}));}catch(e){if(Date.now()-(flushRestoration.lastError||0)>2200){toast(e.message);flushRestoration.lastError=Date.now();}}finally{restoreSending=false;}}
function restoreLive(){const g=room?.game;if(!g||g.type!=='restore')return;const p=me();$$('[data-progress]').forEach(el=>el.textContent=g.progress);if($('#wave-timer'))$('#wave-timer').textContent=Math.max(0,Math.ceil((g.nextEvent-now())/1000))+'s';if($('#restore-event'))$('#restore-event').textContent=g.event?.name||'';if($('#restore-event-text'))$('#restore-event-text').textContent=g.event?.text||'';if(p){const value=Math.min(10,(p.energy||0)+Math.max(0,now()-room.serverNow)/1000*1.5);if($('#energy-count'))$('#energy-count').textContent=Math.floor(value)+' / 10';if($('#restore-combo'))$('#restore-combo').textContent='COMBO ×'+Math.min(3,1+Math.floor((now()-p.lastRestore<2200?p.combo:0)/4)*.5);if($('#restore-rush'))$('#restore-rush').textContent=p.rushUntil>now()?'RUSH! FREE ACTIONS '+Math.ceil((p.rushUntil-now())/1000)+'s':'';}}
function animateRestoration(){let sent=0;const loop=t=>{if(!$('#restore-board')||room?.game?.type!=='restore'||room.game.phase!=='restore')return;drawRestoration($('#restore-board'));if(t-sent>250){sent=t;flushRestoration();}animation=requestAnimationFrame(loop);};animation=requestAnimationFrame(loop);}
function drawRestoration(canvas){const g=room.game,ctx=canvas.getContext('2d'),time=now()/1000;ctx.imageSmoothingEnabled=false;ctx.fillStyle='#d7e9e2';ctx.fillRect(0,0,900,600);ctx.fillStyle='#033532';ctx.font='700 20px Oswald, sans-serif';ctx.textAlign='left';ctx.fillText('FROM FOREST',12,32);ctx.fillStyle='#136e7c';ctx.fillText('TO REEF',590,32);ctx.font='10px DM Sans, sans-serif';ctx.fillStyle='#54746b';ctx.fillText('PLANT + WATER = GROWTH',12,51);ctx.fillText('CLEAR + CORAL = LIVING REEF',590,51);
for(const c of g.cells||[]){ctx.save();ctx.translate(7+c.x*73,70+c.y*58);ctx.scale(73/49,58/39);const x=0,y=0;const mature=['tree','coral'].includes(c.type);const variant=(c.x*7+c.y*3)%3;ctx.fillStyle=c.zone==='reef'?['#93cfc9','#8dc9c6','#a4d4cc'][variant]:mature?['#6da275','#7dad79','#78aa70'][variant]:['#b6a580','#bbab85','#b1a17c'][variant];ctx.fillRect(x,y,48,38);ctx.fillStyle=c.zone==='reef'?'#70b6b1':'#978c6f';ctx.fillRect(x,y+35,48,3);ctx.fillStyle='#ffffff15';ctx.fillRect(x+2,y+2,44,2);
if(c.type==='rock'){ctx.fillStyle='#84998f';ctx.fillRect(x+14,y+12,22,15);ctx.fillRect(x+19,y+8,12,5);ctx.fillStyle='#a6b5a6';ctx.fillRect(x+17,y+12,11,4);}
if(c.type==='litter'){ctx.fillStyle='#e4ded0';ctx.fillRect(x+11,y+14,10,13);ctx.fillStyle='#ac8073';ctx.fillRect(x+27,y+13,11,8);ctx.fillStyle='#648a87';ctx.fillRect(x+29,y+8,5,7);ctx.fillStyle='#fbf8ea';ctx.fillRect(x+13,y+11,6,3);}
if(c.type==='seedling'){ctx.fillStyle=c.zone==='reef'?'#a66ca0':'#547c46';ctx.fillRect(x+23,y+12,3,18);ctx.fillStyle=c.zone==='reef'?'#d697c2':'#73bd55';ctx.fillRect(x+14,y+12,10,7);ctx.fillRect(x+26,y+7,10,8);if(!c.watered){ctx.strokeStyle='#c7f50a';ctx.lineWidth=2;ctx.strokeRect(x+18,y+27,14,5);ctx.fillStyle='#317b97';ctx.fillRect(x+36,y+24,5,7);}else{ctx.fillStyle='#ecfff6';ctx.fillRect(x+36,y+7,3,3);}}
if(c.type==='tree'){const sway=Math.sin(time*1.3+c.id)*1.2;ctx.fillStyle='#486c49';ctx.fillRect(x+22,y+16,6,17);ctx.fillStyle='#195a3d';ctx.fillRect(x+10+sway,y+3,28,19);ctx.fillRect(x+16+sway,y-4,17,12);ctx.fillStyle='#4a9853';ctx.fillRect(x+13+sway,y+2,14,10);ctx.fillStyle='#76b55b';ctx.fillRect(x+17+sway,y-2,7,6);if(c.id%13===0){ctx.fillStyle='#c7f50a';ctx.fillRect(x+31,y+10,4,4);}}
if(c.type==='coral'){ctx.strokeStyle=['#e69da8','#c59edb','#e4bc78'][variant];ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(x+24,y+31);ctx.lineTo(x+24,y+9);ctx.moveTo(x+24,y+23);ctx.lineTo(x+12,y+16);ctx.lineTo(x+11,y+9);ctx.moveTo(x+24,y+19);ctx.lineTo(x+36,y+12);ctx.lineTo(x+36,y+6);ctx.stroke();if(c.id%5===0){const fx=x+((time*8+c.id*3)%39);ctx.fillStyle='#f2e8a2';ctx.fillRect(fx,y+7,7,4);ctx.fillRect(fx-3,y+6,3,6);}}
if(c.type==='fire'){ctx.fillStyle='#b65f42';ctx.fillRect(x+4,y+4,40,30);ctx.fillStyle='#f0a250';ctx.fillRect(x+15,y+12,18,18);ctx.fillStyle='#f9db71';ctx.fillRect(x+20,y+5+Math.sin(time*7+c.id)*3,8,19);ctx.strokeStyle='#fef8df';ctx.lineWidth=2;ctx.strokeRect(x+3,y+3,42,31);}
if(c.type==='gold'){ctx.fillStyle=Math.sin(time*7)>0?'#c7f50a':'#f5ffb4';ctx.beginPath();ctx.moveTo(x+24,y+3);ctx.lineTo(x+29,y+13);ctx.lineTo(x+40,y+18);ctx.lineTo(x+29,y+23);ctx.lineTo(x+24,y+34);ctx.lineTo(x+19,y+23);ctx.lineTo(x+8,y+18);ctx.lineTo(x+19,y+13);ctx.closePath();ctx.fill();}
if(c.id===restoreHover&&restorePointer){ctx.strokeStyle='#033532';ctx.lineWidth=3;ctx.strokeRect(x+1,y+1,46,36);}ctx.restore();}
for(const p of g.popups||[]){const age=now()-p.at;if(age>1600||age<0)continue;ctx.globalAlpha=1-age/1600;ctx.fillStyle='#033532';ctx.font='700 13px DM Sans, sans-serif';ctx.textAlign='center';ctx.fillText(p.text,43+p.x*73,69+p.y*58-age/60);ctx.globalAlpha=1;}
ctx.fillStyle='#033532';ctx.font='11px DM Sans, sans-serif';ctx.textAlign='left';ctx.fillText('GROW TOGETHER. COMPETE FOR YOUR OWN SCORE.',12,578);ctx.fillStyle='#638c76';ctx.fillRect(12,545,875,8);ctx.fillStyle='#c7f50a';ctx.fillRect(12,545,875*Math.min(1,g.progress/g.target),8);}
